512	interface Article {
513	  id: string;
514	  title: string;
515	  summary: string;
516	  body: string;
517	  status: 'draft';
518	  createdAt: string;
519	  version: number;
520	}
521	interface StoredArticle {
522	  id?: unknown;
523	  title?: unknown;
524	  summary?: unknown;
525	  body?: unknown;
526	  status?: unknown;
527	  createdAt?: unknown;
528	  version?: unknown;
529	}
530	interface DraftInput {
531	  title: string;
532	  summary: string;
533	  body: string;
534	}
535	
536	class HttpError extends Error {
537	  status: number;
538	  constructor(status: number, message: string) {
539	    super(message);
540	    this.name = 'HttpError';
541	    this.status = status;
542	  }
543	}
544	
545	function respond(res: ServerResponse, status: number, value: unknown, html = false): void {
546	  const body = html ? String(value) : JSON.stringify(value);
547	  res.writeHead(status, {
548	    'content-type': html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
549	    'content-length': Buffer.byteLength(body),
550	  });
551	  res.end(body);
552	}
