583	function readArticles(): Article[] {
584	  let parsed: unknown;
585	  try {
586	    parsed = JSON.parse(readFileSync(dataFile, 'utf8'));
587	  } catch (error) {
588	    throw new Error(`unable to read articles: ${(error as Error).message}`);
589	  }
590	  if (!Array.isArray(parsed)) throw new Error('unable to read articles: stored data is not a list');
591	  const articles: Article[] = [];
592	  for (const record of parsed) {
593	    const article = normalizeArticle(record);
594	    if (article) articles.push(article);
595	  }
596	  return articles;
597	}
598	
599	function writeArticles(records: Article[]): void {
600	  const tmpFile = join(dataDir, `.articles.${process.pid}.tmp`);
601	  try {
602	    writeFileSync(tmpFile, `${JSON.stringify(records, null, 2)}\n`);
603	    renameSync(tmpFile, dataFile);
604	  } catch (error) {
605	    try { rmSync(tmpFile, { force: true }); } catch { /* best effort cleanup */ }
606	    throw new Error(`unable to save articles: ${(error as Error).message}`);
607	  }
608	}
609	
610	// Serialize read-modify-write so concurrent saves never lose or corrupt records.
611	let writeQueue: Promise<void> = Promise.resolve();
612	function enqueueWrite<T>(task: () => T): Promise<T> {
613	  const run = writeQueue.then(task);
614	  writeQueue = run.then(() => undefined, () => undefined);
615	  return run;
616	}
617	
618	function readBody(req: IncomingMessage): Promise<string> {
619	  return new Promise((resolve, reject) => {
620	    const chunks: Buffer[] = [];
621	    let size = 0;
622	    let settled = false;
623	    req.on('data', (chunk: unknown) => {
624	      if (settled) return;
625	      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
626	      size += buf.length;
627	      if (size > MAX_BODY_BYTES) {
628	        settled = true;
629	        reject(new HttpError(400, 'request body is too large'));
630	        req.destroy();
631	        return;
632	      }
633	      chunks.push(buf);
634	    });
635	    req.on('end', () => {
636	      if (!settled) resolve(Buffer.concat(chunks).toString('utf8'));
637	    });
638	    req.on('error', (error: Error) => {
639	      if (!settled) reject(new HttpError(400, `could not read request body: ${error.message}`));
640	    });
641	  });
642	}
643	
644	function parseJsonObject(text: string): Record<string, unknown> {
645	  let payload: unknown;
646	  try {
647	    payload = JSON.parse(text);
648	  } catch (error) {
649	    throw new HttpError(400, `invalid JSON: ${(error as Error).message}`);
650	  }
651	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
652	    throw new HttpError(400, 'request body must be a JSON object');
653	  }
654	  return payload as Record<string, unknown>;
655	}
656	
657	function validateDraftInput(data: Record<string, unknown>): DraftInput {
658	  if (typeof data.title !== 'string') {
659	    throw new HttpError(400, 'title must be a string');
660	  }
661	  const title = data.title.trim();
662	  if (title.length === 0) {
663	    throw new HttpError(400, 'title must not be empty or only whitespace');
664	  }
665	  let summary = '';
666	  if (Object.prototype.hasOwnProperty.call(data, 'summary')) {
667	    if (typeof data.summary !== 'string') throw new HttpError(400, 'summary must be a string when provided');
668	    summary = data.summary;
669	  }
670	  if (typeof data.body !== 'string') {
671	    throw new HttpError(400, 'body must be a string');
672	  }
673	  return { title, summary, body: data.body };
674	}
675	
676	// Updates carry the version the editor loaded; stale versions are rejected.
677	// As with creation, summary may be omitted (saved as empty string) but a
678	// present non-string summary is a 400.
679	function validateUpdateInput(data: Record<string, unknown>): DraftInput & { version: number } {
680	  const fields = validateDraftInput(data);
681	  if (typeof data.version !== 'number' || !Number.isInteger(data.version) || data.version < 0) {
682	    throw new HttpError(400, 'version must be a non-negative integer');
683	  }
684	  return { ...fields, version: data.version };
685	}
686	
687	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
688	  let route: string;
689	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; }
690	  catch { respond(res, 400, { error: 'invalid request path' }); return; }
691	
692	  // /api/articles/:id (match the raw path first; decode only the captured id)
693	  const itemMatch = /^\/api\/articles\/([^/]+)$/.exec(route);
694	  let itemId: string | null = null;
695	  if (itemMatch) {
696	    try { itemId = decodeURIComponent(itemMatch[1]); }
697	    catch { respond(res, 400, { error: 'invalid article id encoding' }); return; }
698	  }
699	
700	  if (!['/', '/health', '/api/articles'].includes(route) && !itemMatch) {
701	    respond(res, 404, { error: 'not found' });
702	    return;
703	  }
704	
705	  if (route === '/') {
706	    if (req.method === 'GET') { respond(res, 200, PAGE, true); return; }
707	    methodNotAllowed(res, 'GET');
708	    return;
709	  }
710	  if (route === '/health') {
711	    if (req.method === 'GET') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
712	    methodNotAllowed(res, 'GET');
713	    return;
714	  }
715	
716	  if (itemMatch && itemId !== null) {
717	    const id = itemId;
718	    if (req.method === 'GET') {
719	      const articles = readArticles();
720	      const article = articles.find((a) => a.id === id);
721	      if (!article) throw new HttpError(404, 'article not found');
722	      respond(res, 200, { article });
723	      return;
724	    }
725	    if (req.method === 'PUT') {
726	      const text = await readBody(req);
727	      const data = parseJsonObject(text);
728	      const fields = validateUpdateInput(data);
729	      const result = await enqueueWrite((): { status: number; article: Article } => {
730	        const records = readArticles();
731	        const index = records.findIndex((a) => a.id === id);
732	        if (index === -1) {
733	          throw new HttpError(404, 'article not found');
734	        }
735	        const current = records[index];
736	        if (fields.version !== current.version) {
737	          // 409 carries the currently saved article for side-by-side comparison.
738	          const conflict = new HttpError(409, 'a newer version of this article has been saved');
739	          (conflict as HttpError & { article?: Article }).article = current;
740	          throw conflict;
741	        }
742	        const updated: Article = {
743	          id: current.id,
744	          title: fields.title,
745	          summary: fields.summary,
746	          body: fields.body,
747	          status: current.status,
748	          createdAt: current.createdAt,
749	          version: current.version + 1,
750	        };
751	        records[index] = updated;
752	        writeArticles(records);
753	        return { status: 200, article: updated };
754	      });
755	      respond(res, result.status, { article: result.article });
756	      return;
757	    }
758	    methodNotAllowed(res, 'GET, PUT');
759	    return;
760	  }
761	
762	  // /api/articles
763	  if (req.method === 'GET') {
764	    respond(res, 200, { [RESOURCE]: readArticles() });
765	    return;
766	  }
767	  if (req.method === 'POST') {
768	    const text = await readBody(req);
769	    const data = parseJsonObject(text);
770	    const fields = validateDraftInput(data);
771	    const article: Article = {
772	      id: randomUUID(),
773	      title: fields.title,
774	      summary: fields.summary,
775	      body: fields.body,
776	      status: 'draft',
777	      createdAt: new Date().toISOString(),
778	      version: 1,
779	    };
780	    await enqueueWrite((): void => {
781	      const records = readArticles();
782	      records.push(article);
783	      writeArticles(records);
784	    });
785	    respond(res, 201, { article });
786	    return;
787	  }
788	  methodNotAllowed(res, 'GET, POST');
789	}
790	
791	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
792	  handle(req, res).catch((error: unknown) => {
793	    if (res.writableEnded) return;
794	    if (error instanceof HttpError) {
795	      const payload: { error: string; article?: Article } = { error: error.message };
796	      const withArticle = error as HttpError & { article?: Article };
797	      if (error.status === 409 && withArticle.article) payload.article = withArticle.article;
798	      respond(res, error.status, payload);
799	      return;
800	    }
801	    respond(res, 500, { error: error instanceof Error ? error.message : 'internal error' });
802	  });
803	});
804	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
805	server.listen(port, host, (): void => {
806	  const address = server.address();
807	  if (address && typeof address !== 'string') {
808	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
809	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
810	  }
811	});
812	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
813	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
814	}
