// 用最小 DOM 桩模拟页面脚本，验证“保存等待期间继续输入不被覆盖”的修复。
import { readFileSync } from 'node:fs';

const html = readFileSync(new URL('./server.ts', import.meta.url), 'utf8');
const script = html.match(/<script>([\s\S]*)<\/script>/)[1];

function makeEl(tag) {
  const el = {
    tagName: String(tag || '').toUpperCase(),
    children: [],
    listeners: {},
    value: '',
    textContent: '',
    className: '',
    hidden: false,
    disabled: false,
    type: '',
    _cls: new Set(),
    classList: {
      add(c) { el._cls.add(c); },
      remove(c) { el._cls.delete(c); },
      contains(c) { return el._cls.has(c); },
    },
    appendChild(c) { el.children.push(c); return c; },
    addEventListener(ev, fn) { (el.listeners[ev] ||= []).push(fn); },
    click() { (el.listeners.click || []).forEach((f) => f()); },
    focus() {},
    reset() { for (const id of ['title', 'summary', 'body']) els[id].value = ''; },
    querySelector(sel) {
      const want = sel.toUpperCase();
      const walk = (n) => {
        for (const c of n.children || []) {
          if (c.tagName === want) return c;
          const r = walk(c);
          if (r) return r;
        }
        return null;
      };
      return walk(el);
    },
  };
  Object.defineProperty(el, 'innerHTML', {
    set(v) { if (v === '') el.children = []; },
    get() { return ''; },
  });
  return el;
}

const ids = ['draft-form', 'title', 'summary', 'body', 'save-btn', 'cancel-btn',
  'status', 'edit-banner', 'conflict-box', 'article-list', 'empty-tip'];
const els = Object.fromEntries(ids.map((id) => [id, makeEl(id)]));

const documentStub = {
  getElementById: (id) => els[id] || null,
  createElement: (tag) => makeEl(tag),
};
const windowStub = { confirm: () => true };

// ---- fetch 桩：响应由测试手动控制 ----
const pending = [];
const responses = [];
function fetchStub(url, opts = {}) {
  const method = opts.method || 'GET';
  const key = method + ' ' + url;
  return new Promise((resolve, reject) => {
    pending.push({ key, opts, resolve, reject });
  });
}
function respondNext(key, status, json) {
  const i = pending.findIndex((p) => p.key === key);
  if (i < 0) throw new Error('no pending request for ' + key + '; pending: ' + pending.map((p) => p.key));
  const [p] = pending.splice(i, 1);
  p.resolve({ ok: status >= 200 && status < 300, status, json: () => Promise.resolve(json) });
}
const flush = () => new Promise((r) => setTimeout(r, 0));

// ---- 测试数据 ----
const V1 = { id: 'a1', title: '标题', summary: '摘要', body: '第一段', status: 'draft', createdAt: '2026-01-01T00:00:00.000Z', version: 1 };

// 执行页面脚本
const run = new Function('document', 'window', 'fetch', script);
run(documentStub, windowStub, fetchStub);
await flush();

// 初始列表加载
respondNext('GET /api/articles', 200, { articles: [V1] });
await flush();

// 点击列表中的“编辑”按钮
const li = els['article-list'].children[0];
const card = li.children[0];
const actions = card.children.find((c) => c.className === 'actions');
const editBtn = actions.children[0];
editBtn.click();
await flush();
respondNext('GET /api/articles/a1', 200, { article: V1 });
await flush();

const assert = (cond, msg) => { if (!cond) { console.error('FAIL: ' + msg); process.exitCode = 1; } else console.log('ok: ' + msg); };
assert(els.title.value === '标题' && els.body.value === '第一段', '进入编辑态，表单载入已保存内容');
assert(els['save-btn'].textContent === '保存修改', '按钮变为“保存修改”');

// 第一次提交：正文“第一段”
els['draft-form'].listeners.submit[0]({ preventDefault() {} });
assert(els['save-btn'].disabled === true, '保存中按钮禁用，禁止重复提交');
// 等待响应期间继续输入第二段，并清空摘要
els.body.value = '第一段\n\n第二段';
els.summary.value = '';
// 响应返回：只保存了“第一段”和旧摘要
respondNext('PUT /api/articles/a1', 200, { article: { ...V1, body: '第一段', version: 2 } });
await flush();

assert(els.body.value === '第一段\n\n第二段', '等待期间补写的第二段被保留，未被覆盖');
assert(els.summary.value === '', '等待期间清空的摘要保留为空，未被旧值填回');
assert(els.title.value === '标题', '未改动的标题字段同步为已保存值');
assert(els.status.textContent.includes('已保存') && els.status.textContent.includes('未保存'), '提示本次已保存且仍有未保存修改：' + els.status.textContent);
assert(els.status.className.includes('warn'), '未保存提示使用 warn 样式');
// 列表只显示实际保存的内容
const li2 = els['article-list'].children[0];
assert(li2.children[0].children[0].textContent === '标题', '列表标题为已保存内容');

// 再次保存：两段一起提交，version 应为 2（不得误报 409）
els['draft-form'].listeners.submit[0]({ preventDefault() {} });
const put2 = pending.find((p) => p.key === 'PUT /api/articles/a1');
const sent = JSON.parse(put2.opts.body);
assert(sent.version === 2, '第二次提交携带更新后的版本号 2，不会误报冲突');
assert(sent.body === '第一段\n\n第二段', '第二次提交正文包含两段');
assert(sent.summary === '', '清空后的摘要随第二次提交保存');
respondNext('PUT /api/articles/a1', 200, { article: { ...V1, summary: '', body: '第一段\n\n第二段', version: 3 } });
await flush();
assert(els.body.value === '第一段\n\n第二段' && els.summary.value === '', '第二次保存后表单与已保存内容一致');
assert(els.status.className.includes('ok') && !els.status.textContent.includes('未保存'), '内容一致时显示普通保存成功，无未保存提示：' + els.status.textContent);

// 失败场景：等待期间的输入也保留
els.body.value = '第一段\n\n第二段\n\n第三段';
els['draft-form'].listeners.submit[0]({ preventDefault() {} });
els.body.value = '第一段\n\n第二段\n\n第三段\n\n第四段';
respondNext('PUT /api/articles/a1', 500, { error: 'disk full' });
await flush();
assert(els.body.value.includes('第四段'), '保存失败时保留失败发生时的全部输入');
assert(els.status.className.includes('err') && els.status.textContent.includes('disk full'), '失败显示明确原因：' + els.status.textContent);
assert(els['save-btn'].disabled === false, '失败后按钮恢复可用');

// 409 场景：保留双方内容
els['draft-form'].listeners.submit[0]({ preventDefault() {} });
respondNext('PUT /api/articles/a1', 409, { error: 'conflict', article: { ...V1, body: '别人的内容', version: 9 } });
await flush();
assert(els.body.value.includes('第四段'), '409 时保留自己的输入');
assert(els['conflict-box'].hidden === false, '409 显示对照区');
console.log('done');
process.exit(process.exitCode || 0);

